entries as (
    select
        rows_as_json.source_key,
        rows_as_json.notice_key,
        rows_as_json.row_json,
        rows_as_json.fact_columns,
        entry.key as column_name,
        json_extract_string(entry.value, '$') as raw_text
    from rows_as_json
    cross join json_each(rows_as_json.row_json) as entry
    where
        json_type(entry.value) = 'VARCHAR'
        and not list_contains(rows_as_json.fact_columns, entry.key)
        and entry.key not in (
            'notice_key', '_loaded_at', '_dlt_id', '_dlt_load_id', 'geom'
        )
)

select
    {{ dbt_utils.generate_surrogate_key([
        'entries.source_key', 'entries.notice_key', 'entries.column_name'
    ]) }} as wording_key,
    entries.source_key,
    entries.notice_key,
    entries.column_name,
    {{ notice_wording_text('entries.raw_text') }} as wording
from entries
where
    {{ notice_is_wording(notice_wording_text('entries.raw_text')) }}
    -- A value the source repeats in a fact column, as a description
    -- that is its title again, is a fact, never wording.
    and not exists (
        select 1
        from json_each(entries.row_json) as fact
        where
            list_contains(entries.fact_columns, fact.key)
            and json_extract_string(fact.value, '$') = entries.raw_text
    )
